<?php
namespace ExcelHerbal\ERP7\Workforce;
use ExcelHerbal\ERP7\Administration\ActingDutyService;
use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;
use ExcelHerbal\ERP7\Database\Transaction;
use ExcelHerbal\ERP7\Domain\DomainException;
use ExcelHerbal\ERP7\Security\Actor;
use ExcelHerbal\ERP7\Security\Audit;
use ExcelHerbal\ERP7\Security\Capabilities;
use ExcelHerbal\ERP7\Security\Guard;
use ExcelHerbal\ERP7\Security\HierarchyScope;
use ExcelHerbal\ERP7\Recovery\GpsPointValidator;

final class WorkforceService{
 public static function attendanceToday(Actor $a):?array{Guard::cap($a,Capabilities::ATT_SELF);self::ensureScheduledAttendance($a);$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT * FROM ".Db::table('attendance')." WHERE company_id=%d AND employee_id=%d AND business_date=%s",$a->companyId,$a->employeeId,Db::today()),ARRAY_A);if(!$r)return null;$r=array_merge($r,GpsDutyPolicy::state($r));$r['latest_gps_at']=$db->get_var($db->prepare("SELECT recorded_at FROM ".Db::table('gps_points')." WHERE company_id=%d AND employee_id=%d AND attendance_id=%d ORDER BY recorded_at DESC,id DESC LIMIT 1",$a->companyId,$a->employeeId,(int)$r['id']));return$r;}
 private static function ensureScheduledAttendance(Actor $a):void{$branch=(int)($a->assignedBranchId??0);if($branch<1||!$a->hasBranch($branch))return;$date=Db::today();$localTime=current_time('H:i:s');if($localTime<GpsDutyPolicy::START)return;$db=Db::wpdb();$leaveCount=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('leave_requests')." WHERE company_id=%d AND employee_id=%d AND status='approved' AND date_from<=%s AND date_to>=%s",$a->companyId,$a->employeeId,$date,$date));$holidayCount=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('holidays')." WHERE company_id=%d AND active=1 AND (branch_id IS NULL OR branch_id=%d) AND holiday_date=%s",$a->companyId,$branch,$date));if($leaveCount>0||$holidayCount>0)return;$t=Db::table('attendance');$startUtc=get_gmt_from_date($date.' '.GpsDutyPolicy::START);$stopUtc=get_gmt_from_date($date.' '.GpsDutyPolicy::STOP);Db::mustQuery($db,$db->prepare("INSERT INTO {$t}(company_id,branch_id,employee_id,business_date,status,check_in_at,created_at) VALUES(%d,%d,%d,%s,'present',%s,%s) ON DUPLICATE KEY UPDATE id=id",$a->companyId,$branch,$a->employeeId,$date,$startUtc,Db::now()));Db::mustUpdate($db,$t,['branch_id'=>$branch,'check_in_at'=>$startUtc,'status'=>'present'],['company_id'=>$a->companyId,'employee_id'=>$a->employeeId,'business_date'=>$date,'check_in_at'=>null]);if($localTime>=GpsDutyPolicy::STOP){Db::mustUpdate($db,$t,['check_out_at'=>$stopUtc],['company_id'=>$a->companyId,'employee_id'=>$a->employeeId,'business_date'=>$date,'check_out_at'=>null]);}}
 public static function checkIn(Actor $a,int $branch,?float $lat,?float $lng):array{throw new DomainException('Duty is automatic from 10:30 AM to 5:00 PM. Manual check-in is disabled.','attendance_manual_disabled',403);}
 public static function checkOut(Actor $a,?float $lat,?float $lng):array{throw new DomainException('Duty is automatic from 10:30 AM to 5:00 PM. Manual check-out is disabled.','attendance_manual_disabled',403);}
 public static function attendanceReport(Actor $a,int $branch,string $from,string $to):array{Guard::branch($a,$branch,Capabilities::ATT_MANAGE);$ids=HierarchyScope::visibleEmployeeIds($a,$branch);if(!$ids)return[];[$from,$to]=Input::dateRange($from,$to,'Attendance period');$visible=implode(',',array_map('intval',$ids));return(array)Db::wpdb()->get_results(Db::wpdb()->prepare("SELECT a.*,e.employee_code,e.full_name FROM ".Db::table('attendance')." a JOIN ".Db::table('employees')." e ON e.id=a.employee_id WHERE a.company_id=%d AND a.branch_id=%d AND a.employee_id IN ({$visible}) AND a.business_date BETWEEN %s AND %s ORDER BY a.business_date DESC,e.full_name",$a->companyId,$branch,$from,$to),ARRAY_A);}
 public static function currentVisit(Actor $a):?array{Guard::cap($a,Capabilities::FIELD_SELF);$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT * FROM ".Db::table('field_visits')." WHERE company_id=%d AND employee_id=%d AND status='in_progress' ORDER BY id DESC LIMIT 1",$a->companyId,$a->employeeId),ARRAY_A);return$r?:null;}
 public static function startVisit(Actor $a,int $branch,?int $party,string $purpose,?float $lat,?float $lng):array{[$lat,$lng]=self::gpsPair($lat,$lng);$purpose=trim($purpose);if($purpose===''||strlen($purpose)>255)throw new DomainException('Field Visit purpose is required and must be 255 characters or fewer.','field_visit_purpose_invalid',422);Guard::branch($a,$branch,Capabilities::FIELD_SELF);return Transaction::run(function()use($a,$branch,$party,$purpose,$lat,$lng){$db=Db::wpdb();if($party){$valid=(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('parties')." WHERE id=%d AND company_id=%d AND branch_id=%d AND status='active'",$party,$a->companyId,$branch));if(!$valid)throw new DomainException('Selected party is not active in this branch.','field_visit_party_invalid',422);}$t=Db::table('field_visits');$open=$db->get_row($db->prepare("SELECT id FROM {$t} WHERE company_id=%d AND employee_id=%d AND status='in_progress' ORDER BY id DESC LIMIT 1 FOR UPDATE",$a->companyId,$a->employeeId),ARRAY_A);if($open)throw new DomainException('Complete current Field Visit first.','field_visit_open',409);Db::mustInsert($db,$t,['company_id'=>$a->companyId,'branch_id'=>$branch,'employee_id'=>$a->employeeId,'party_id'=>$party,'purpose'=>$purpose,'status'=>'in_progress','start_lat'=>$lat,'start_lng'=>$lng,'started_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'field_visit.start','field_visit',$id,['branch_id'=>$branch]);return['id'=>$id,'status'=>'in_progress'];});}
 public static function completeVisit(Actor $a,int $id,?float $lat,?float $lng):array{[$lat,$lng]=self::gpsPair($lat,$lng);Guard::cap($a,Capabilities::FIELD_SELF);return Transaction::run(function()use($a,$id,$lat,$lng){$db=Db::wpdb();$t=Db::table('field_visits');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d AND employee_id=%d FOR UPDATE",$id,$a->companyId,$a->employeeId),ARRAY_A);if(!$r)throw new DomainException('Field Visit not found.','field_visit_not_found',404);if($r['status']!=='in_progress')throw new DomainException('Field Visit already completed.');$updated=$db->update($t,['status'=>'completed','end_lat'=>$lat,'end_lng'=>$lng,'completed_at'=>Db::now()],['id'=>$id]);if($updated===false)throw new DomainException('Unable to complete Field Visit.','field_visit_store_failed',500);Audit::add($a,'field_visit.complete','field_visit',$id,['branch_id'=>(int)$r['branch_id']]);return['id'=>$id,'status'=>'completed'];});}
 public static function leaveMine(Actor $a):array{Guard::cap($a,Capabilities::LEAVE_SELF);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('leave_requests')." WHERE company_id=%d AND employee_id=%d ORDER BY id DESC LIMIT 100",$a->companyId,$a->employeeId),ARRAY_A);}
 public static function leavePending(Actor $a,int $branch):array{Guard::branch($a,$branch,Capabilities::LEAVE_MANAGE);$ids=HierarchyScope::visibleEmployeeIds($a,$branch);if(!$ids)return[];$visible=implode(',',array_map('intval',$ids));$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT lr.*,e.employee_code,e.full_name FROM ".Db::table('leave_requests')." lr JOIN ".Db::table('employees')." e ON e.id=lr.employee_id WHERE lr.company_id=%d AND lr.branch_id=%d AND lr.employee_id IN ({$visible}) AND lr.status='submitted' ORDER BY lr.requested_at,id",$a->companyId,$branch),ARRAY_A);}
 public static function leave(Actor $a,string $type,string $from,string $to,string $reason):array{Guard::cap($a,Capabilities::LEAVE_SELF);[$from,$to]=Input::dateRange($from,$to,'Leave period');$type=trim($type);$reason=trim($reason);if($type==='')throw new DomainException('Leave type is required.','leave_type_required',422);if(strlen($reason)<3)throw new DomainException('Leave reason is required.','leave_reason_required',422);$branch=$a->assignedBranchId;if(!$branch||!$a->hasBranch($branch))throw new DomainException('Active assigned branch required for leave.','branch_access_required',403);return Transaction::run(function()use($a,$type,$from,$to,$reason,$branch){$db=Db::wpdb();$t=Db::table('leave_requests');$overlap=$db->get_row($db->prepare("SELECT id FROM {$t} WHERE company_id=%d AND employee_id=%d AND status IN ('submitted','approved') AND NOT(date_to<%s OR date_from>%s) ORDER BY id LIMIT 1 FOR UPDATE",$a->companyId,$a->employeeId,$from,$to),ARRAY_A);if($overlap)throw new DomainException('Overlapping leave exists.','leave_overlap',409);Db::mustInsert($db,$t,['company_id'=>$a->companyId,'branch_id'=>$branch,'employee_id'=>$a->employeeId,'leave_type'=>$type,'date_from'=>$from,'date_to'=>$to,'reason'=>$reason,'status'=>'submitted','requested_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'leave.request','leave_request',$id,['branch_id'=>$branch,'date_from'=>$from,'date_to'=>$to]);return['id'=>$id,'status'=>'submitted'];});}
 public static function decideLeave(Actor $a,int $id,bool $approve):array{return Transaction::run(function()use($a,$id,$approve){$db=Db::wpdb();$t=Db::table('leave_requests');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Leave not found.','leave_not_found',404);$branch=(int)($r['branch_id']??0);if(!$branch)throw new DomainException('Leave branch snapshot missing.','leave_branch_missing',409);$authority=ActingDutyService::assertAction($a,$branch,'workforce.leave.decision',(int)$r['employee_id']);if($authority['mode']==='permanent')HierarchyScope::assertCanViewEmployee($a,(int)$r['employee_id']);if($r['status']!=='submitted')throw new DomainException('Leave not pending.');if((int)$r['employee_id']===$a->employeeId)throw new DomainException('Cannot approve own leave.','maker_checker_required',409);$status=$approve?'approved':'rejected';$updated=$db->update($t,['status'=>$status,'decided_by'=>$a->employeeId,'decided_at'=>Db::now()],['id'=>$id]);if($updated===false)throw new DomainException('Leave decision failed.','leave_store_failed',500);Audit::add($a,'leave.'.$status,'leave_request',$id,['branch_id'=>$branch]);return['id'=>$id,'status'=>$status];});}
 private static function gpsPair(?float $lat,?float $lng):array{if($lat===null&&$lng===null)return[null,null];if($lat===null||$lng===null)throw new DomainException('Latitude and longitude must be supplied together.','gps_invalid',422);try{$g=GpsPointValidator::normalize(['lat'=>$lat,'lng'=>$lng]);}catch(\InvalidArgumentException $e){throw new DomainException($e->getMessage(),'gps_invalid',422);}return[$g['latitude'],$g['longitude']];}
}
